{
  "book_code": "2ES",
  "verses": [
    {
      "text_ar": "فحدث لما دخل ابني إلى مخدع عرسه أنه سقط ومات.",
      "chapter": 10,
      "verse": 1
    },
    {
      "text_ar": "حينئذ أطفأنا كلنا السرج، وقام جميع جيراني لتعزيتي، فبقيت ساكتة حتى الليلة الثانية.",
      "chapter": 10,
      "verse": 2
    },
    {
      "text_ar": "وحدث عندما كفّوا جميعهم عن تعزيتي وحثي على السكوت، أنني قمت ليلاً وهربت وجئت إلى هذا الحقل كما ترين.",
      "chapter": 10,
      "verse": 3
    },
    {
      "text_ar": "والآن لست أنوي الرجوع إلى المدينة، بل أن أقيم هنا، ولا آكل ولا أشرع، بل أنوح وأصوم بلا انقطاع حتى أموت.",
      "chapter": 10,
      "verse": 4
    },
    {
      "text_ar": "ثم تركت الأفكار التي كنت مستغرقاً فيها وأجبتها بغضب:",
      "chapter": 10,
      "verse": 5
    },
    {
      "text_ar": "أيتها المرأة الحمقاء جداً، أما ترين مناحتنا وما حدث لنا؟",
      "chapter": 10,
      "verse": 6
    },
    {
      "text_ar": "لأن صهيون أمنا جميعاً ممتلئة حزناً وذليلة جداً.",
      "chapter": 10,
      "verse": 7
    },
    {
      "text_ar": "حق لنا الآن أن ننوح بعمق إذ أننا ننوح جميعاً، وأن نحزن إذ نحن جميعاً في حزن، وأما أنت فتنويين على ابن واحد.",
      "chapter": 10,
      "verse": 8
    },
    {
      "text_ar": "اسألي الأرض فهي ستخبرك أنها هي التي ينبغي لها أن تنوح على الكثيرين الذين ينبتون عليها.",
      "chapter": 10,
      "verse": 9
    },
    {
      "text_ar": "فمنها كان مبدأ الجميع، وآخرون سيأتون، وهوذا تقريباً كلهم يسيرون إلى الهلاك وجمهورهم مقضي عليه بالهلاك التام.",
      "chapter": 10,
      "verse": 10
    },
    {
      "text_ar": "فمن ينبغي له إذاً أن ينوح أكثر: هي التي فقدت جمهوراً عظيماً هكذا، أم أنت التي تحزنين على واحد فقط؟",
      "chapter": 10,
      "verse": 11
    },
    {
      "text_ar": "ولكن إن قلت لي: ليست مناحتي مثل مناحة الأرض، لأني فقدت ثمرة بطني التي ولدتها بأوجاع وحملتها بأحزان،",
      "chapter": 10,
      "verse": 12
    },
    {
      "text_ar": "وأما ما للأرض فهو على طريقة الأرض، والجمهور الحاضر فيها ذهب كما أتى.",
      "chapter": 10,
      "verse": 13
    },
    {
      "text_ar": "حينئذ أقول لك: وكما أنك ولدت بأحزان هكذا أعطت الأرض أيضاً ثمرتها أي البشر منذ البدء للذي صنعها.",
      "chapter": 10,
      "verse": 14
    },
    {
      "text_ar": "فالآن احفظي حزنك لنفسك واحتملي بشجاعة الشدائد التي أصابتك.",
      "chapter": 10,
      "verse": 15
    },
    {
      "text_ar": "فإن اعترفت بأن قضاء الله عادل، فإنك ستنالين ابنك في وقته وتمدحين بين النساء.",
      "chapter": 10,
      "verse": 16
    },
    {
      "text_ar": "امضي إذن إلى المدينة إلى زوجك.",
      "chapter": 10,
      "verse": 17
    },
    {
      "text_ar": "فقالت لي: لن أعمل ذلك. لن أدخل المدينة بل أموت هنا.",
      "chapter": 10,
      "verse": 18
    },
    {
      "text_ar": "فشرعت أتكلم معها أيضاً وقلت:",
      "chapter": 10,
      "verse": 19
    },
    {
      "text_ar": "لا تقومي بذلك، بل دعيني أقنعك بسبب شدائد صهيون، وتعزي بسبب حزن أورشليم.",
      "chapter": 10,
      "verse": 20
    }
  ]
}
